local InstancePathManager = require(script.Parent.Parent.Core.InstancePathManager)

return function(moduleScript: ModuleScript)
	assert(moduleScript, "can't require beacuse argument is nil")
	assert(
		moduleScript:IsA("ModuleScript"),
		`can't require beacuse argument is not ModuleScript : ` .. InstancePathManager.GetPath(moduleScript)
	)

	local success, result = pcall(function()
		return require(moduleScript)
	end)

	if not success then
		warn(`can't require beacuse inner error : ` .. InstancePathManager.GetPath(moduleScript))
		error(result)
	end

	return result
end
